function mrImpactSummary(r,plan){let p=mrImpact(r.pair,plan);return `<div class="mr-impact-grid">${kv({'主档案':esc(p.after.name)+' · '+p.main.id,'待并入档案':p.children.length+' 份，原档案保留并标记从属','合并后客户类型':p.type,'归属客服':esc(p.after.consultant)})}${kv({'保留订单':p.kept.length+' 笔（含历史订单）','流退进行中订单':p.returned.length+' 笔','取消排课':p.cancelled.length+' 条','保留支付记录合计':money(p.totalPayments)})}</div>${p.returned.length?`<div style="margin-top:16px">${table(['将流退订单','所属档案','当前状态','流退类型','人头变化 / 考核'],p.returned.map(o=>[o.id,esc(r.pair.find(c=>c.id===o.origin)?.name||o.origin),o.status,o.status==='已到店'?'合并到店流退':'合并预约流退',esc(o.consultant)+' · '+(o.status==='已到店'?'到店':'预约')+'人头 −1（合并流退不纳入考核）']))}</div>`:'<p class="mr-inline-note">无订单需要流退，历史订单全部迁入主档案。</p>'}<p class="mr-inline-note">覆盖全部 ${r.pair.length} 份档案。支付流水不删除，不自动退款，不跨订单转移预约金；全部档案快照、订单来源与身份标识共同留存。</p>`+pcPeopleImpact({...r,snapshot:{after:p.after}})}
function mhData(r){return {before:r.snapshot?.before||r.pair||[],after:r.snapshot?.after||null}}
function mhArchived(r){return r.archived||mrTime(r.retainUntil)<Date.now()}
function mhInfo(rows){return '<dl class="mh-info">'+rows.map(([label,value,wide])=>'<div'+(wide?' class="mh-wide"':'')+'><dt>'+label+'</dt><dd>'+value+'</dd></div>').join('')+'</dl>'}
function mhText(value){return esc(value===0?0:value||'未记录')}
function mhProfile(c,title,snapshot=false){let phones=[...new Set([c.oldPhone,...(c.phones||[])].filter(x=>x&&x!==c.phone))],rows=[['姓名',mhText(c.name)],['主手机号',mhText(c.phone)],['性别',mhText(c.gender)],['生日',mhText(c.birthday)],['档案门店',mhText(c.store)],['归属客服',mhText(c.consultant)],['档案 ID',uiId(c.id)],['客户类型',mhText(c.customerType)],['备注',mhText(c.remark),true]];if(phones.length)rows.push(['备用手机号',phones.map(esc).join('　'),true]);if(snapshot)rows.push(['建档时间',mhText(c.created)],['白条 / 充值',(c.white==null?'未记录':money(c.white))+' / '+(c.recharge==null?'未记录':money(c.recharge))],['UnionID',mhText([...new Set([c.unionId,...(c.unionIds||[])].filter(Boolean))].join('、')),true],['企微 ID',mhText([...new Set([c.externalId,...(c.externalIds||[])].filter(Boolean))].join('、')),true]);return contentModule(title,mhInfo(rows),'','mh-profile')}
function mhRelation(r){let {before,after}=mhData(r);return '<div class="mh-relation"><strong>'+before.map(c=>esc(c.name)).join(' + ')+'</strong><span>→</span><strong>'+esc(after?.name||'结果未保存')+'</strong></div><div class="mh-meta"><span>记录 ID '+uiId(r.id)+'</span><span>'+esc(r.method)+'</span><span>'+esc(r.time)+'</span><span>'+esc(r.author)+'</span></div>'}
function mhNote(r){return r.revoked?'<p class="mh-state-note"><strong>已撤销</strong> · '+esc(r.revokedAt||'撤销时间未记录')+'。下方保留当次合并的历史结果，参与档案已恢复独立。</p>':(r.followUp||mrCorrection(r))?'<p class="mh-state-note">下方为本次执行时的结果；后续业务和纠错变更请在当前客户档案中查看。</p>':''}
function mhTabs(r,key,nested=false){let prefix=nested?'mh-nested':'mh-record';return `<div class="mh-tabs" role="tablist" aria-label="合并记录分类">${MH_TABS.map(([k,t],i)=>`<button id="${prefix}-${k}" role="tab" aria-controls="${prefix}-content" aria-selected="${key===k}" tabindex="${key===k?0:-1}" class="${key===k?'active':''}" onclick="mhSetTab(${esc(mrQuote(r.id))},'${k}',${nested})" onkeydown="pcRecordTabKey(event,${i})">${t}</button>`).join('')}</div>`}
function mhSetTab(id,key,nested=false){if(!MH_TABS.some(x=>x[0]===key))return;if(nested){pcViewRecord(id,key);return}if(mrTask?.kind!=='record'||mrTask.id!==id)return;mrTask.tab=key;render();$('#mergeRecordPanel .merge-drawer-body')?.scrollTo(0,0);$('#mh-record-'+key)?.focus()}
function mhPickSnapshot(id,cid,nested=false){let r=state.mergeRecords.find(x=>x.id===id);if(!r||!mhSnapshotPeople(r).some(c=>c.id===cid)||!mhCanViewSnapshot(r))return;if(nested){pcRecordModalState={...(pcRecordModalState||{}),id,tab:'compare',snapshotId:cid};pcViewRecord(id,'compare')}else{mrTask.snapshotId=cid;mhSetTab(id,'compare')}}
function mhBack(r,nested,tab){return nested?btn('返回合并记录',`pcViewRecord(${mrQuote(r.id)},'${tab}')`):btn('返回合并记录','closeModal()')}
function mhDetail(r,title,content,nested=false,tab='overview'){modal(title,'<div class="mh-view">'+content+'</div>',mhBack(r,nested,tab),true)}
function mhUnavailable(){return '<div class="mh-unavailable">完整快照已归档，仅展示保留的执行摘要。</div>'}
function mhOverview(r,nested=false){let {before,after}=mhData(r),archived=mhArchived(r),summary=mhRelation(r)+mhNote(r),participants=table(['参与客户','手机号','档案门店 / 客服','本次处理','操作'],before.map(c=>[esc(c.name)+'<div class="ma-caption">ID '+uiId(c.id)+'</div>',mhText(uiPhone(c.phone)),mhText(c.store)+'<div class="ma-caption">'+mhText(c.consultant)+'</div>',c.id===r.plan.mainId?'保留为主档案':'并入主档案',archived?'—':btn('查看快照',`mhPickSnapshot(${mrQuote(r.id)},${mrQuote(c.id)},${nested})`,'text')]));return summary+(archived?mhUnavailable():after?mhProfile(after,'合并后客户资料'):'<div class="mh-unavailable">此记录未保存合并后的客户资料。</div>')+contentModule('参与档案',participants)+contentModule('执行信息',mhInfo([['采用规则',esc(r.rule.name)+' V'+esc(r.rule.version)],['主档案依据',mhText(r.plan.mainReason)],['冷静期结束',mhText(r.coolingUntil)],['快照保留至',mhText(r.retainUntil)]]),btn('规则依据',`mhRuleDetail(${mrQuote(r.id)},${nested})`,'text'))}
function mhOrderRows(r){let {before,after}=mhData(r),seen=new Set(),rows=[];for(let c of before)for(let o of c.orders||[]){if(seen.has(o.id))continue;seen.add(o.id);rows.push({c,before:o,after:after?.orders?.find(x=>x.id===o.id)||null})}for(let o of after?.orders||[])if(!seen.has(o.id)){seen.add(o.id);rows.push({c:before.find(c=>[o.sourceOrigin,o.origin,o.sourceCustomerId].includes(c.id))||null,before:null,after:o})}return rows}
function mhReturned(x){return !!x.before&&mrActive(x.before)&&!!x.after&&(x.after.status==='已流退'||!!x.after.mergeReturnType&&x.after.mergeReturnType!==x.before.mergeReturnType)}
function mhOrderAction(x){return !x.after?'结果未保存':!x.before?'原状态未保存':mhReturned(x)?'合并流退':mrActive(x.before)?'保留订单':'历史订单保留'}
function mhAppointment(x){let a=x.before?.appointmentAt||x.before?.scheduledAt||'',b=x.after?.appointmentAt||x.after?.scheduledAt||'';if(!x.after)return '结果未保存';if(x.before&&(a&&!b||x.after.scheduleStatus==='合并取消'&&x.before.scheduleStatus!=='合并取消'))return '已取消'+(a?' · '+a:'');if(x.after.scheduleStatus==='合并取消')return '原排客已取消';if(x.before&&!mrActive(x.before))return a||b?'历史记录 · '+(b||a):'无排客记录';return b?'保留 · '+b:x.before?'未安排':'原排客信息未保存'}
function mhOrders(r,nested=false){if(mhArchived(r))return mhUnavailable();let rows=mhOrderRows(r),sorted=rows.slice().sort((a,b)=>Number(mrActive(b.before||b.after))-Number(mrActive(a.before||a.after))),returned=rows.filter(mhReturned),cancelled=rows.filter(x=>mhAppointment(x).startsWith('已取消')),summary='<div class="mh-meta"><span>保留 '+rows.filter(x=>x.after&&!mhReturned(x)).length+' 笔订单</span><span>合并流退 '+returned.length+' 笔</span><span>取消 '+cancelled.length+' 条排客</span>'+(rows.some(x=>!x.after)?'<span>部分订单结果未保存</span>':'')+'</div>';
 return contentModule('订单处理结果',summary+table(['订单 / 来源档案','合并前业务','门店 / 人员','关键时间','执行结果','操作'],sorted.map(x=>{let o=x.before||x.after,c=x.c,info=maOrderInfo(c||{},o);return [esc(info.name)+'<div class="ma-caption">订单 '+uiId(o.id)+'</div><div class="ma-caption">'+(c?esc(c.name)+' · '+uiId(c.id):'来源未保存')+'</div>',(x.before?badge(o.status):'原状态未保存')+'<div class="ma-caption">预约金 '+money(o.deposit||0)+'</div><div class="ma-caption">订单 '+money(o.amount||0)+'</div>',mhText(info.store)+'<div class="ma-caption">预约：'+mhText(info.bookingBy)+'</div><div class="ma-caption">接待：'+mhText(info.receiver)+'</div>','<div>预约 '+esc(info.appointment||'未安排')+'</div><div class="ma-caption">创建 '+mhText(info.created)+'</div><div class="ma-caption">到店 '+mhText(info.arrived)+'</div>',mhOrderAction(x)+'<div class="ma-caption">'+(x.after?'合并后 '+esc(x.after.status):'')+'</div><div class="ma-caption">'+esc(mhAppointment(x))+'</div>',btn('订单详情',`mhOrderDetail(${mrQuote(r.id)},${mrQuote(o.id)},${nested})`,'text')]}))+(rows.length?'':'<p class="mh-empty">本次快照无订单记录。</p>'),'','mh-orders')}
function mhOrderDetail(id,oid,nested=false){let r=state.mergeRecords.find(x=>x.id===id);if(!r||mhArchived(r))return;let x=mhOrderRows(r).find(x=>(x.before||x.after).id===oid);if(!x)return;let o=x.before||x.after,info=maOrderInfo(x.c||{},o),after=mhData(r).after,payments=(after?.payments||[]).filter(p=>p.orderId===oid),tab=nested?pcRecordModalState?.tab||'orders':mrTask?.tab||'orders';mhDetail(r,'订单处理详情',contentModule('订单与处理结果',mhInfo([['订单',uiId(oid)+' · '+esc(info.name)],['来源档案',x.c?esc(x.c.name)+' · '+uiId(x.c.id):'未保存'],['合并前状态',mhText(x.before?.status)],['合并后状态',mhText(x.after?.status)],['订单门店',mhText(info.store)],['订单金额',money(o.amount||0)],['预约人员',mhText(info.bookingBy)],['接待人员',mhText(info.receiver)],['合并前客服',mhText(x.before?.consultant)],['合并后客服',mhText(x.after?.consultant)],['创建时间',mhText(info.created)],['预约金支付',mhText(info.paid)],['到店时间',mhText(info.arrived)],['排客处理',esc(mhAppointment(x))],['处理依据',mhText(r.plan.orderReasons?.[oid]),true]]))+contentModule('关联支付流水',table(['流水 ID','类型','金额','发生时间'],payments.map(p=>[uiId(p.id),mhText(p.type),cxSign(pcPaymentAmount(p)),mhText(p.at)]))+(payments.length?'':'<p class="mh-empty">快照未保存关联支付流水。</p>')),nested,tab)}
function mhMigration(r,nested=false){let after=mhData(r).after,summary=contentModule('数据迁移结果',table(['数据类型','数量','执行结果'],(r.migrations||[]).map(m=>[esc(m.name),esc(m.count),esc(m.detail)])),!mhArchived(r)&&after?btn('逐条迁移明细',`mhMigrationDetail(${mrQuote(r.id)},${nested})`,'text'):'');if(mhArchived(r)||!after)return mhUnavailable()+summary;let before=mhData(r).before,checks=r.reconciliation||pcReconciliation(before,after);return summary+contentModule('数据完整性',table(['核对项','合并前应有值','合并后值','结果'],checks.map(x=>[esc(x.label),x.expected===null?'未保存明细':esc(x.expected),esc(x.actual),badge(x.status,x.ok?'green':'orange')]))+(r.evidenceVersion===1?'':'<p class="mh-footnote">按已保存快照对照；历史记录未保存执行时的核对报告。</p>'),btn('统计与人头变化',`mhStatsDetail(${mrQuote(r.id)},${nested})`,'text'))}
function mhMigrationDetail(id,nested=false){let r=state.mergeRecords.find(r=>r.id===id);if(!r||mhArchived(r))return;mhDetail(r,'逐条迁移明细',pcMigrationTable(r),nested,'changes')}
function mhStatsDetail(id,nested=false){let r=state.mergeRecords.find(r=>r.id===id);if(!r||mhArchived(r)||!mhData(r).after)return;mhDetail(r,'统计与人头变化',pcStatsTable([mhData(r).after])+pcPeopleImpact({...r,pair:mhData(r).before}),nested,'changes')}
function mhEnsureSnapshotExamples(r){
 if(!r?.demo)return false;if(r.snapshotExamples?.version===1&&r.snapshotExamples.recordId===r.id)return false;
 let before=mhData(r).before;if(!before.length)return false;
 r.snapshotExamples={version:1,recordId:r.id,before:before.map((original,index)=>{
  let c=clone(original);if(qaComplete(c)&&c.payments?.length)return c;
  let prefix='SNAP-'+r.id+'-'+c.id,id=key=>prefix+'-'+key,base=mrTime(r.time),at=days=>mrDate(base-days*86400000),store=c.store||'A01 · 静安店',staff=c.consultant||'顾问陈',teacher=['护理师王','护理师许','护理师刘'][index%3];
  let row=(key,values)=>({id:id(key),snapshotExample:true,...values});
  for(let key of ['orders','payments','assets','walletAccounts','serviceRecords','followups','performanceEntries'])c[key]||=[];
  let order=row('ORDER',{name:'面部护理套餐',status:'已完成',amount:1500,deposit:300,store,consultant:staff,bookingBy:staff,receiver:teacher,createdAt:at(12),paidAt:at(12),scheduledAt:at(10),arrivedAt:at(10),customerType:'老客'});
  let asset=row('ASSET',{name:'面部护理权益',orderId:order.id,purchased:6,gifted:0,consumed:2,refunded:0,expired:0,remaining:4,frozen:0,unit:'次',unitValue:250});
  c.orders.push(order);c.assets.push(asset);
  c.payments.push(row('DEPOSIT',{orderId:order.id,type:'预约金收取',amount:300,at:at(12),status:'已完成'}),row('PAYMENT',{orderId:order.id,type:'订单尾款',amount:700,at:at(11),status:'已完成'}));
  let opening=c.walletAccounts.length?0:Number(c.white)||0;
  c.walletAccounts.push(row('WALLET',{label:'白条账户（补充示例）',kind:'本金',openingBalance:opening,balance:opening,frozen:0,entries:[row('RECHARGE',{type:'充值',amount:500,at:at(12)}),row('DEBIT',{type:'账户消耗',amount:-500,orderId:order.id,at:at(11)})]}));
  c.serviceRecords.push(row('SERVICE',{name:'面部护理',orderId:order.id,assetId:asset.id,qty:2,amount:500,employee:teacher,store,at:at(10)}));
  c.followups.push(row('FOLLOWUP',{name:'护理效果回访',orderId:order.id,status:'已回访',handler:staff,dueAt:at(8),content:'客户反馈良好，已核对剩余 4 次护理权益'}));
  c.performanceEntries.push(row('SALE',{orderId:order.id,metric:'销售业绩',employee:staff,store,amount:1500,unit:'元',commissionAmount:75,paidAmount:0}),row('PERFORMANCE',{orderId:order.id,metric:'服务消耗业绩',employee:teacher,store,amount:500,unit:'元',commissionAmount:50,paidAmount:0}));
  c.snapshotSupplemented=true;return c;
 })};return true;
}
function mhSnapshotPeople(r){if(mhEnsureSnapshotExamples(r))persist();return r.demo&&r.snapshotExamples?.recordId===r.id?r.snapshotExamples.before:mhData(r).before}
function mhCanViewSnapshot(r){return !mhArchived(r)||!!(r.demo&&r.snapshotExamples?.recordId===r.id)}
function mhSampleLabel(x){return x.snapshotExample?' '+badge('示例',''):''}
function mhSnapshotOrderTable(r,c,nested){let orders=(c.orders||[]).slice().sort((a,b)=>Number(mrActive(b))-Number(mrActive(a)));return contentModule('合并前订单',table(['订单 / 项目','原状态','金额 / 预约金','门店 / 人员','预约时间','操作'],orders.map(o=>{let info=maOrderInfo(c,o);return [esc(info.name)+mhSampleLabel(o)+'<div class="ma-caption">订单 '+uiId(o.id)+'</div>',badge(o.status),money(o.amount||0)+'<div class="ma-caption">预约金 '+money(o.deposit||0)+'</div>',mhText(info.store)+'<div class="ma-caption">预约：'+mhText(info.bookingBy)+' / 接待：'+mhText(info.receiver)+'</div>',esc(info.appointment||'未安排'),btn('订单详情',`mhSnapshotOrderDetail(${mrQuote(r.id)},${mrQuote(c.id)},${mrQuote(o.id)},${nested})`,'text')]}))+(orders.length?'':'<p class="mh-empty">此客户快照无订单。</p>'))}
function mhSnapshot(r,nested=false){
 let before=mhSnapshotPeople(r);if(!mhCanViewSnapshot(r))return mhUnavailable();let selected=(nested?pcRecordModalState:mrTask)?.snapshotId,c=before.find(x=>x.id===selected)||before.find(x=>x.id===r.plan.mainId)||before[0];if(!c)return '<div class="mh-unavailable">此记录未保存合并前快照。</div>';
 let tabs='<div class="mh-person-tabs" role="tablist" aria-label="选择历史客户快照">'+before.map((x,i)=>`<button role="tab" aria-selected="${x.id===c.id}" tabindex="${x.id===c.id?0:-1}" class="${x.id===c.id?'active':''}" onclick="mhPickSnapshot(${esc(mrQuote(r.id))},${esc(mrQuote(x.id))},${nested})" onkeydown="pcRecordTabKey(event,${i})">${esc(x.name)}<span>ID ${uiId(x.id)}</span></button>`).join('')+'</div>';
 let note=c.snapshotSupplemented?'<div class="mh-sample-note">'+badge('含补充示例','')+'<span>标记“示例”的业务用于原型验收，不参与实际迁移或纠错。</span>'+(!mhArchived(r)?btn('原始快照',`mhOriginalSnapshot(${mrQuote(r.id)},${mrQuote(c.id)},${nested})`,'text'):'<span>当前为归档示例预览</span>')+'</div>':mhArchived(r)?'<p class="mh-footnote">归档示例预览</p>':'';
 return tabs+note+mhProfile(c,'合并前客户资料',true)+mhSnapshotOrderTable(r,c,nested)+contentModule('合并前业务资料',mhInfo([['项目与资产',(c.assets||[]).length+' 项'],['支付流水',(c.payments||[]).length+' 笔'],['账户与资金',(c.walletAccounts||[]).length+' 个账户'],['回访与服务',(c.followups||[]).length+' 条回访 / '+(c.serviceRecords||[]).length+' 条服务'],['员工业绩',(c.performanceEntries||[]).length+' 条'],['通话 / 影像',(c.calls||[]).length+' / '+(c.images||[]).length],['标签',(c.tags||[]).map(esc).join('、')||'无',true],['加微记录',(c.wechat||[]).map(x=>esc(x.by)+' · '+esc(x.at)).join('<br>')||'无记录',true]]),btn('查看业务明细',`mhSnapshotDetail(${mrQuote(r.id)},${mrQuote(c.id)},${nested})`,'text'));
}
function mhSnapshotBusiness(c){
 let list=(title,heads,rows)=>contentModule(title,table(heads,rows)+(rows.length?'':'<p class="mh-empty">此快照未保存该类明细。</p>'));
 let assets=list('项目与资产',['项目 / 关联订单','购买 / 赠送','已消耗 / 退款 / 失效','剩余 / 冻结'],(c.assets||[]).map(a=>[mhText(a.name)+mhSampleLabel(a)+'<div class="ma-caption">订单 '+uiId(a.orderId)+'</div>',bpNum(a.purchased)+' / '+bpNum(a.gifted),bpNum(a.consumed)+' / '+bpNum(a.refunded)+' / '+bpNum(a.expired),bpNum(a.remaining)+' / '+bpNum(a.frozen)+' '+esc(a.unit||'次')]));
 let payments=list('支付流水',['流水 ID / 类型','关联订单','金额','发生时间'],(c.payments||[]).map(p=>[uiId(p.id)+' · '+mhText(p.type)+mhSampleLabel(p),p.orderId?uiId(p.orderId):'无',cxSign(pcPaymentAmount(p)),mhText(p.at)]));
 let accounts=list('账户余额',['账户','期初余额','当前余额','冻结 / 可用'],(c.walletAccounts||[]).map(a=>[mhText(a.label)+mhSampleLabel(a),money(a.openingBalance||0),money(a.balance||0),money(a.frozen||0)+' / '+money((Number(a.balance)||0)-(Number(a.frozen)||0))]));
 let funds=list('账户资金流水',['流水 ID / 账户','业务类型 / 关联订单','金额','发生时间'],(c.walletAccounts||[]).flatMap(a=>(a.entries||[]).map(p=>[uiId(p.id)+'<div class="ma-caption">'+mhText(a.label)+'</div>',mhText(p.type)+mhSampleLabel(p)+(p.orderId?'<div class="ma-caption">订单 '+uiId(p.orderId)+'</div>':''),cxSign(pcPaymentAmount(p)),mhText(p.at)])));
 let follows=list('回访记录',['事项 / 关联订单','状态','负责人','时间 / 回访内容'],(c.followups||[]).map(f=>[mhText(f.name)+mhSampleLabel(f)+'<div class="ma-caption">订单 '+uiId(f.orderId)+'</div>',mhText(f.status),mhText(f.handler),mhText(f.dueAt)+'<div class="ma-caption">'+mhText(f.content)+'</div>']));
 let services=list('服务记录',['项目 / 关联订单','扣减资产 / 数量','服务员工 / 门店','服务时间'],(c.serviceRecords||[]).map(f=>[mhText(f.name)+mhSampleLabel(f)+'<div class="ma-caption">订单 '+uiId(f.orderId)+'</div>',uiId(f.assetId)+' / '+bpNum(f.qty)+' 次',mhText(f.employee)+'<div class="ma-caption">'+mhText(f.store)+'</div>',mhText(f.at)]));
 let staff=list('员工业绩',['业绩类型 / 关联业务','员工 / 门店','业绩基数','应计 / 已发提成'],(c.performanceEntries||[]).map(f=>[mhText(f.metric)+mhSampleLabel(f)+'<div class="ma-caption">'+(f.orderId?'订单 '+uiId(f.orderId):f.fundId?'流水 '+uiId(f.fundId):'无关联业务')+'</div>',(f.beneficiaries?.length?f.beneficiaries.map(x=>mhText(x.employee)+' · '+mhText(x.store)+' · '+bpNum(x.share)+'%').join('<br>'):mhText(f.employee)+' · '+mhText(f.store)),bpNum(f.amount)+' '+esc(f.unit||'元'),money(f.commissionAmount||0)+' / '+money(f.paidAmount||0)]));
 let knownFunds=new Set((c.walletAccounts||[]).flatMap(a=>(a.entries||[]).map(p=>p.id))),legacy=(c.whiteEntries||[]).filter(p=>!knownFunds.has(p.id));if(legacy.length)funds+=list('原白条流水',['流水 ID','类型','金额','发生时间'],legacy.map(p=>[uiId(p.id),mhText(p.type),cxSign(pcPaymentAmount(p)),mhText(p.at)]));
 let other=list('其他业务记录',['类型 / 记录 ID','内容','人员 / 状态','时间'],[['projects','外协项目'],['tickets','售后'],['calls','通话'],['images','影像'],['checkins','签到'],['adjustments','调账']].flatMap(([key,label])=>(c[key]||[]).map(x=>[label+' · '+uiId(x.id),mhText(x.name||x.summary||x.type),mhText(x.handler||x.by||x.status),mhText(x.at||x.serviceDate)])));
 return assets+payments+accounts+funds+follows+services+staff+other;
}
function mhSnapshotDetail(id,cid,nested=false){let r=state.mergeRecords.find(x=>x.id===id);if(!r)return;let c=mhSnapshotPeople(r).find(x=>x.id===cid);if(!c||!mhCanViewSnapshot(r))return;mhDetail(r,'合并前业务明细 · '+c.name,(c.snapshotSupplemented?'<p class="mh-footnote">标记“示例”的记录为补充验收数据，原执行快照未改写。</p>':'')+mhSnapshotBusiness(c),nested,'compare')}
function mhSnapshotOrderDetail(id,cid,oid,nested=false){let r=state.mergeRecords.find(x=>x.id===id);if(!r)return;let c=mhSnapshotPeople(r).find(x=>x.id===cid),o=c?.orders?.find(x=>x.id===oid);if(!o||!mhCanViewSnapshot(r))return;let info=maOrderInfo(c,o);mhDetail(r,'合并前订单详情',contentModule(esc(info.name)+mhSampleLabel(o),mhInfo([['订单 ID',uiId(o.id)],['客户',esc(c.name)+' · '+uiId(c.id)],['原状态',mhText(o.status)],['金额 / 预约金',money(o.amount||0)+' / '+money(o.deposit||0)],['门店',mhText(info.store)],['客服',mhText(o.consultant)],['预约人员',mhText(info.bookingBy)],['接待人员',mhText(info.receiver)],['创建时间',mhText(info.created)],['预约时间',mhText(info.appointment)],['支付时间',mhText(info.paid)],['到店时间',mhText(info.arrived)]])),nested,'compare')}
function mhOriginalSnapshot(id,cid,nested=false){let r=state.mergeRecords.find(x=>x.id===id);if(!r||mhArchived(r))return;let c=mhData(r).before.find(x=>x.id===cid);if(!c)return;mhDetail(r,'原始合并前快照 · '+c.name,mhProfile(c,'合并前客户资料',true)+contentModule('原订单',table(['订单 ID','项目','状态','金额'],(c.orders||[]).map(o=>[uiId(o.id),mhText(o.name),mhText(o.status),money(o.amount||0)])))+mhSnapshotBusiness(c),nested,'compare')}
function mhRuleDetail(id,nested=false){let r=state.mergeRecords.find(x=>x.id===id);if(!r)return;mhDetail(r,'本次合并的规则依据',contentModule('采用方案',mhInfo([['规则',esc(r.rule.name)+' V'+esc(r.rule.version)],['主档案依据',mhText(r.plan.mainReason)],['订单处理',r.plan.composerVersion?'人工逐笔核对，按保存方案执行':mhText(r.plan.arbitrationRule)],['实际主档案',uiId(r.plan.mainId)]]))+pcTraceTable(r),nested,'overview')}
function mhLogs(r){let app=state.mergeApplications.find(a=>a.id===r.applicationId),rows=[['记录 ID',uiId(r.id)],['执行方式',mhText(r.method)],['执行时间',mhText(r.time)],['操作人',mhText(r.author)],['触发场景',mhText(r.trigger)],['匹配依据',mhText(r.match)]];if(r.applicationId)rows.push(['关联申请',uiId(r.applicationId)],['申请人',mhText(app?.author)],['申请说明',mhText(app?.reason),true],['核实材料',app?.evidence?.map(esc).join('、')||'无',true]);return contentModule(app?'执行与申请信息':'执行信息',mhInfo(rows))+contentModule('操作记录',table(['时间','操作人','操作内容'],(r.logs||[]).map(l=>[mhText(l.at),mhText(l.by),mhText(l.content)])))}
function mhContent(r,key,nested=false){return key==='orders'?mhOrders(r,nested):key==='changes'?mhMigration(r,nested):key==='compare'?mhSnapshot(r,nested):key==='logs'?mhLogs(r):mhOverview(r,nested)}
function mhActions(r){let c=mrCorrection(r),s=mrStatus(r);if(r.revoked)return '';if(s==='冷静期中'&&!r.followUp&&!c)return btn('撤销合并',`mrUndoAsk(${mrQuote(r.id)})`,'danger');if(c)return btn('查看纠错工单',`mrGoCorrection(${mrQuote(r.id)})`,'primary');if(['已合并','部分已纠错'].includes(s))return btn('发起纠错',`mrStartCorrection(${mrQuote(r.id)})`,'primary');if(s==='快照已归档')return btn('手工调账',`mrArchived(${mrQuote(r.id)})`);return ''}
function mhDrawer(r){let key=MH_TABS.some(x=>x[0]===mrTask.tab)?mrTask.tab:'overview';mrTask.tab=key;return `<div class="merge-drawer-backdrop" onclick="if(event.target===this&&!this.dataset.closing&&!document.querySelector('#modal>[data-overlay-layer]'))mrClose()"><section id="mergeRecordPanel" class="merge-drawer ma-composer mh-record" role="dialog" aria-modal="true" aria-label="合并记录"><header class="merge-drawer-head"><div class="ma-heading"><h2>合并记录</h2>${mrBadge(mrStatus(r))}</div><button class="icon-btn" aria-label="关闭合并记录" onclick="mrClose()">${icon('close')}</button></header>${mhTabs(r,key)}<div class="merge-drawer-body mh-view" data-drawer-scroll="merge-record"><div id="mh-record-content" role="tabpanel" aria-labelledby="mh-record-${key}">${mhContent(r,key)}</div></div><footer class="merge-drawer-foot"><div class="actions">${btn('关闭','mrClose()')}</div><div class="actions">${mhActions(r)}</div></footer></section></div>`}
function mrRecordOverview(r){let p=mrImpact(r.pair,r.plan),status=mrStatus(r);return contentModule('合并概况',body(mrPairCards(r)+`<div class="mr-meta">${kv({'合并编号':r.id,'档案数量':r.pair.length+' 份（1 个主档案）','状态':mrBadge(status),'合并方式':r.method,'触发场景':r.trigger,'触发原因':esc(r.match),'执行时间':r.time,'操作人':esc(r.author),'关联处理':r.applicationId?btn(r.applicationId,pcRenderingNestedRecord?`pcReadApplication(${mrQuote(r.applicationId)})`:`mrOpen('application',${mrQuote(r.applicationId)})`,'text'):'系统自动执行','采用规则':esc(r.rule.name)+' V'+r.rule.version,'冷静期结束':r.coolingUntil,'快照保留至':r.retainUntil,'后续业务':r.followUp?'已有后续业务记录':'未发生后续业务'})}</div>`))+(r.revoked?contentModule('撤销结果',body(kv({'撤销时间':r.revokedAt||'示例撤销记录','恢复档案':r.snapshot.before.map(c=>esc(c.name)+' · '+c.id).join('<br>'),'当前状态':'全部参与档案恢复独立，迁移数据已回退','历史追溯':'原合并方案和处理明细继续保留，不再作为生效结果'}))):contentModule('执行结果',body(mrImpactSummary(r,r.plan))))+(status==='冷静期中'?contentModule('冷静期',body(`<p class="small">冷静期结束前限制：${['退款操作','白条充值 / 消耗','资产变更','手动修改客户基本信息'].filter((x,i)=>r.rule.config.threshold.limits[i]).join('、')||'未配置限制'}。</p><p class="mr-inline-note">${r.followUp?'已有后续业务记录，不能直接撤销；冷静期结束后可发起纠错。':'尚未发生后续业务，可基于本次快照撤销，恢复全部参与档案。'}</p>`)):'')}
function mrChanges(r){if(r.archived||mrTime(r.retainUntil)<Date.now())return contentModule('处理摘要',body('<p class="small muted">完整快照已归档，以下为保留的执行摘要。</p>')+table(['数据类型','数量','处理方式'],r.migrations.map(m=>[m.name,m.count,esc(m.detail)])));let p=mrImpact(r.pair,r.plan);return contentModule('判定过程',body(kv({'主档案判定':esc(r.plan.mainReason),'订单仲裁规则':esc(r.plan.arbitrationRule||'人工选择'),'执行处理动作':esc(r.plan.action==='perOrder'?'逐笔订单选择（'+p.returned.length+' 笔流退）':ARB_ACTIONS[r.plan.action]),'人工调整':r.method==='人工合并'?'主子、订单及冲突字段采用执行前保存的方案':'按当时生效规则执行'})))+contentModule('数据迁移明细',table(['数据类型','数量','处理方式'],r.migrations.map(m=>[m.name,m.count,esc(m.detail)])))+contentModule('订单处理结果',table(['订单编号','合并前状态','合并后状态','支付记录','排课处理'],p.all.map(o=>{let returned=p.returned.some(x=>x.id===o.id);return [o.id,o.status,returned?o.status==='已到店'?'合并到店流退':'合并预约流退':o.status,money(o.deposit)+' · 原流水保留',returned&&o.scheduledAt?'排课已取消并记录通知':'保留原记录']})))+contentModule('合并后主档案',body(kv({'档案编号':p.after.id,'客户姓名':esc(p.after.name),'主手机号':esc(p.after.phone),'保留手机号':esc(p.after.phones.join('、')),'标签':esc(p.after.tags.join('、')),'订单数':p.after.orders.length+' 笔','白条余额':money(p.after.white),'客户类型':p.type})))+pcMergeEvidence(r)}
function mrPick(side=-1){mrPickerSide=side;mrPickerQuery='';mrPickerSelected=new Set();modal('添加客户档案',queryModule(`<div class="search">${icon('search')}<input id="mrPickerInput" aria-label="搜索可合并客户" placeholder="姓名、当前或旧手机号、档案编号、加微客服" value="" oninput="mrPickerQuery=this.value"></div>`,'mrPickerSearch()','mrPickerReset()')+'<div id="mrPickerRows">'+mrPickerRows()+'</div><div class="mr-selection-meta" id="mrPickerSummary">已勾选 0 份，可跨搜索条件选择多份档案。</div>',btn('取消','closeModal()')+btn('添加所选档案','mrPickAddSelected()','primary'),true)}
function mrPickerRows(){let q=uiQuery(mrPickerQuery).toLowerCase(),selected=new Set(mrTask.pair.map(c=>c.id)),rows=state.mergeCustomers.filter(c=>mrEligible(c)&&!selected.has(c.id)&&(!q||[c.name,c.id,c.phone,c.oldPhone,c.consultant].join(' ').toLowerCase().includes(q)));return table(['选择','客户档案','手机号 / 旧手机号','门店 / 加微客服'],rows.map(c=>[`<input type="checkbox" aria-label="添加档案 ${c.name} ${c.id}" ${mrPickerSelected.has(c.id)?'checked':''} onchange="mrPickerToggle('${c.id}',this.checked)">`,'<strong>'+esc(c.name)+'</strong><div class="tiny muted">'+c.id+'</div>',esc(c.phone||'无手机号')+'<div class="tiny muted">'+esc(c.oldPhone||'无旧手机号')+'</div>',esc(c.store)+'<div class="tiny muted">'+esc(c.consultant)+'</div>']))+(!rows.length?empty('暂无可添加的客户档案','已选或已合并从属档案不会重复显示。'):'')}
function mrPickerSearch(){$('#mrPickerRows').innerHTML=mrPickerRows()}
function mrPickerReset(){mrPickerQuery='';$('#mrPickerInput').value='';mrPickerSearch()}
function mrPickCommit(id){mrPickerSelected.add(id);mrPickAddSelected()}
function mrSaveDraft(){mrTask.savedAt=now();state.mergeApplicationDraft=clone(mrTask);state.mergeApplicationDraft.dirty=false;mrTask.dirty=false;persist();mrClose(true);toast('合并申请草稿已保存')}
function mrSubmit(){if(mrTask?.kind!=='new')return;if(mrTask.plan?.composerVersion&&!maRequireMain(mrTask))return;let pair=mrTask.pair,key=mrPairKey(pair);if(pair.length<2||new Set(pair.map(c=>c.id)).size!==pair.length){toast('请至少选择 2 份不同的客户档案');return}let existing=state.mergeApplications.find(a=>['待审核','已通过','执行失败'].includes(a.status)&&a.id!==mrTask.retryFrom&&!a.supersededBy&&mrPairKey(a.pair)===key);if(existing){mgAttachRequest(existing);delete state.mergeApplicationDraft;persist();mrOpen('application',existing.id);toast('已关联现有事项，申请方案与材料可在申请记录中查看');return}if(mrExcluded(pair)){modal('部分档案已确认不合并','<p>所选档案包含已确认独立的客户组合。请移除不属于同一人的档案后再提交。</p>',btn('返回调整','closeModal()'));return}let merged=state.mergeRecords.find(r=>!r.revoked&&mrPairKey(r.pair)===key);if(merged){mrOpen('record',merged.id);toast('这些档案已经合并');return}if(pair.some(c=>state.mergeCustomers.find(x=>x.id===c.id)?.status==='已合并-从属')){toast('档案状态已变化，请更换已合并的档案');return}let rule=clone(mrTask.rule),plan=clone(mrTask.plan),reasons=mrInterceptions(pair,plan,rule),candidate=state.mergeCandidates?.find(g=>g.id===mrTask.candidateId)||state.mergeCandidates?.find(g=>!g.excluded&&mrPairKey(mcMembers(g))===key),a={id:mrNext('MA',state.mergeApplications),pair:clone(pair),rule,plan,status:'待审核',source:candidate?reasons.length?'系统拦截':candidate.source==='凌晨清洗'?'批量清洗':'系统检测':'人工提交',trigger:candidate?.trigger||'人工申请',match:candidate?.match||mrTask.reasonType,reason:mrTask.reason.trim()||'未填写核实说明',reasonType:mrTask.reasonType,candidateId:candidate?.id||'',requestSource:mrTask.candidateId?'system':'manual',retryFrom:mrTask.retryFrom||'',evidence:clone(mrTask.evidence),reasons,author:'张三',handler:'张三',store:pair.find(c=>c.id===plan.mainId)?.store||pair[0].store,time:now(),logs:[],demo:true};mrEvent(a,'提交 '+pair.length+' 份档案的合并申请，尚未迁移任何数据');if(mrTask.retryFrom){let old=state.mergeApplications.find(x=>x.id===mrTask.retryFrom);if(old){old.supersededBy=a.id;mrEvent(old,'重新核对后提交 '+a.id)}}apSeal(a,'merge',mrTask.requestSource==='system'||!!mrTask.candidateId);state.mergeApplications.unshift(a);if(candidate)mrEvent(candidate,'提交合并申请 '+a.id+'，涉及 '+pair.length+' 份档案');delete state.mergeApplicationDraft;persist();mrTask={kind:'application',id:a.id,tab:'overview',plan:clone(a.plan),dirty:false};mgSelected.clear();apOpen('merge',a.id);toast('完整合并方案已提交审核，通过后由系统执行')}
function mrApprove(){let a=mrCurrent();if(a?.review){apOpen('merge',a.id);return}toast('请先提交完整方案，再进入审核管理审批')}
function mrDecisionAsk(type){let a=mrCurrent();if(!a||a.status!=='待审核')return;let title=type==='independent'?'确认所选档案不合并':type==='withdraw'?'撤回合并申请':'驳回合并申请';modal(title,`<p class="small">${type==='independent'?'将本次 '+a.pair.length+' 份档案两两标记为独立客户并加入排除名单，后续检测跳过这些客户组合。':'本次不迁移任何数据，保留申请及处理记录。'}</p><div style="margin-top:16px">${field('处理说明（选填）','<textarea id="mrDecisionNote" aria-label="合并处理说明" placeholder="说明核实结果或处理原因"></textarea>')}</div>`,btn('取消','closeModal()')+btn(title,`mrDecision('${type}')`,'primary'))}
function mrDecision(type){let a=mrCurrent();if(!a||a.status!=='待审核')return;let note=$('#mrDecisionNote')?.value.trim()||({independent:'经核实为不同客户，不合并（示例）',withdraw:'申请人撤回本次申请（示例）',reject:'材料尚不足以确认同一人，请补充核实后重新申请（示例）'}[type]);a.status=type==='independent'?'确认不合并':type==='withdraw'?'已撤回':'已驳回';a.reviewNote=note;a.reviewedAt=now();if(type==='independent')mrExcludeMembers(a.pair);else {let g=state.mergeCandidates.find(g=>g.id===a.candidateId);if(g&&mrPairKey(mcMembers(g))===mrPairKey(a.pair))g.closedKey=mrPairKey(mcMembers(g))}mrEvent(a,a.status+'：'+note);mrTask.dirty=false;persist();closeModal();render();toast('已'+(type==='independent'?'标记独立客户并加入排除名单':type==='withdraw'?'撤回申请':'驳回申请'))}
function mrBatchDecision(){let ids=[...mrSelected].filter(id=>state.mergeApplications.some(a=>a.id===id&&a.status==='待审核'));if(!ids.length){toast('请在申请列表左侧选择待审核申请');return}modal('批量确认不合并',`<p>将选中的 ${ids.length} 组档案标记为独立客户并加入排除名单，不会迁移业务数据。</p>`,btn('取消','closeModal()')+btn('确认不合并','mrCommitBatch()','primary'))}
function mrCommitBatch(){let n=0;for(let id of mrSelected){let a=state.mergeApplications.find(x=>x.id===id);if(a?.status!=='待审核')continue;a.status='确认不合并';a.reviewNote='批量核实为独立客户（示例）';mrExcludeMembers(a.pair);mrEvent(a,'批量确认不合并，加入排除名单');n++}mrSelected.clear();persist();closeModal();render();toast(n+' 组档案已确认不合并')}
function mrTransfer(){let a=mrCurrent();modal('转交合并申请',field('处理人',select(['张三','李四','周敏','总部数据运营'],a.handler,'id="mrHandler" aria-label="新的合并处理人"')),btn('取消','closeModal()')+btn('确认转交','mrTransferCommit()','primary'))}
function mrTransferCommit(){let a=mrCurrent(),next=$('#mrHandler').value;a.handler=next;mrEvent(a,'将申请转交给 '+next);persist();closeModal();render();toast('已转交给 '+next)}
function mrExecuteAsk(){let a=mrCurrent();if(a)apOpen('merge',a.id)}
function mrExecute(){let a=mrCurrent();return a?apExecuteMerge(a.id):false}
function mrAllExcluded(pair){for(let i=0;i<pair.length;i++)for(let j=i+1;j<pair.length;j++)if(!mrExcluded([pair[i],pair[j]]))return false;return pair.length>1}
function mrExcludedKeys(pair){let keys=[];for(let i=0;i<pair.length;i++)for(let j=i+1;j<pair.length;j++)keys.push(mrPairKey([pair[i],pair[j]]));return keys}
function mrExcludeMembers(pair){for(let key of mrExcludedKeys(pair))if(!state.mergeExcludedPairs.includes(key))state.mergeExcludedPairs.push(key)}
function mrSelectedMembersUI(r,editable){let main=mrTask.plan.mainId;return table(['序号','客户档案','手机号 / 旧手机号','门店 / 归属客服','进行中订单 / 白条','主档案','操作'],r.pair.map((c,i)=>[String(i+1).padStart(2,'0'),'<strong>'+esc(c.name)+'</strong><div class="tiny muted">'+c.id+'</div>',esc(c.phone||'无手机号')+'<div class="tiny muted">'+esc(c.oldPhone||'无旧手机号')+'</div>',esc(c.store)+'<div class="tiny muted">'+esc(c.consultant)+'</div>',c.orders.filter(mrActive).length+' 笔 / '+money(c.white),`<label class="mr-main-choice"><input type="radio" name="mrSelectedMain" aria-label="保留 ${esc(c.name)} ${c.id} 为主档案" ${main===c.id?'checked':''} ${editable?`onchange="mrSetMain('${c.id}')"`:'disabled'}>保留为主</label>`,editable?btn('移除',`mrRemoveMember(${mrQuote(c.id)})`,'text'):'—']))}
function mrRemoveMember(id){if(mrTask?.kind!=='new')return;mrTask.pair=mrTask.pair.filter(c=>c.id!==id);maPrepare(mrTask);mrTask.dirty=true;render()}
function mrPickerToggle(id,checked){checked?mrPickerSelected.add(id):mrPickerSelected.delete(id);let el=$('#mrPickerSummary');if(el)el.textContent='已勾选 '+mrPickerSelected.size+' 份，可跨搜索条件选择多份档案。'}
function mrPickAddSelected(){let additions=[...mrPickerSelected].map(id=>state.mergeCustomers.find(c=>c.id===id)).filter(c=>c&&mrEligible(c)&&!mrTask.pair.some(x=>x.id===c.id));if(!additions.length){toast('请在列表左侧选择需要添加的档案');return}mrTask.pair.push(...clone(additions));maPrepare(mrTask);mrTask.dirty=true;closeModal();render();toast('已添加 '+additions.length+' 份档案')}
function mrSetOrder(id,action){let r=mrTask.kind==='new'?mrTask:mrCurrent();if(!maEditable())return;if(!r.pair.some(c=>c.orders.some(o=>o.id===id&&mrActive(o))))return;mrTask.plan.orderChoices||={};mrTask.plan.orderChoices[id]=action==='return'?'return':'keep';mrTask.dirty=true;render()}
function mcActiveApplication(g){let key=mrPairKey(mcMembers(g));return state.mergeApplications.find(a=>['待审核','已通过','执行失败'].includes(a.status)&&!a.supersededBy&&(a.candidateId===g.id||mrPairKey(a.pair)===key))}
function mcStatus(g){let members=mcMembers(g);if(g.excluded||mrAllExcluded(members))return '已排除';if(members.length<=1)return '已合并';let a=mcActiveApplication(g);if(a)return a.status==='已通过'?'待执行':a.status==='执行失败'?'待重新申请':'待审核';return g.hits.length?'前置拦截':'待确认'}
function mcLinkedRecords(g){return state.mergeRecords.filter(r=>r.candidateId===g.id||r.pair.filter(c=>g.memberIds.includes(c.id)).length>=2)}
function mcDetailRecord(g){if(!g)return null;return {...g,pair:clone(g.detectedMembers),plan:mrPlan(g.detectedMembers,g.rule),reason:g.basis,evidence:[],reasons:g.hits.map(h=>h.reason),status:mcStatus(g)}}
function mcOpenLoaded(id){let g=state.mergeCandidates.find(x=>x.id===id);if(!g)return;mrFocus=document.activeElement;mrTask={kind:'candidate',id,tab:'overview',plan:mrPlan(g.detectedMembers,g.rule),dirty:false};render();$('#mergeRecordPanel .icon-btn')?.focus()}
function mcHandle(id){let g=state.mergeCandidates.find(x=>x.id===id);if(!g)return;let a=mcActiveApplication(g);if(a&&a.status!=='执行失败'){mrOpen('application',a.id);return}if(mcStatus(g)==='已合并'){let r=mcLinkedRecords(g).find(r=>!r.revoked);if(r)mrOpen('record',r.id);return}if(mcStatus(g)==='已排除'){toast('该客户组已排除，保留检测与处理记录');return}mrNew(undefined,id)}
function mcSetScope(scope){mcScope=scope;mcPage=1;mcFilter={q:'',store:'',kind:'',source:'',from:'',to:''};mcApplied=clone(mcFilter);render()}
function mcSearch(){if(mcFilter.from&&mcFilter.to&&mcFilter.from>mcFilter.to){toast('开始日期不能晚于结束日期');return}mcApplied=clone(mcFilter);mcPage=1;render()}
function mcReset(){mcFilter={q:'',store:'',kind:'',source:'',from:'',to:''};mcSearch()}
function mcRows(){let f=mcApplied;return state.mergeCandidates.filter(g=>{let done=['已合并','已排除'].includes(mcStatus(g));return (mcScope==='done'?done:!done)&&(!f.q||[g.id,g.match,g.basis,...g.detectedMembers.flatMap(c=>[c.name,c.id,c.phone,c.oldPhone])].join(' ').includes(uiQuery(f.q)))&&(!f.store||g.detectedMembers.some(c=>c.store===f.store))&&(!f.kind||(f.kind==='blocked'?g.hits.length>0:g.hits.length===0))&&(!f.source||g.source===f.source)&&(!f.from||g.time.slice(0,10)>=f.from)&&(!f.to||g.time.slice(0,10)<=f.to)}).sort((a,b)=>b.time.localeCompare(a.time))}
function mergeCandidatesPage(){return mgPage(false)}
function mcList(){let all=mcRows(),pages=Math.max(1,Math.ceil(all.length/6));mcPage=Math.max(1,Math.min(mcPage,pages));let rows=all.slice((mcPage-1)*6,mcPage*6);return table(['检测编号 / 时间','疑似客户档案','匹配依据 / 来源','前置检测结果','门店','处理进度','操作'],rows.map(g=>{let status=mcStatus(g),a=mcActiveApplication(g);return [`<button class="inline-link mono" onclick="mcOpen(${esc(mrQuote(g.id))})">${g.id}</button><div class="tiny muted">${g.time.slice(0,16)}</div>`,`<strong>${g.detectedMembers.length} 份档案</strong><div class="tiny">${g.detectedMembers.map(c=>esc(c.name)).join('、')}</div>`,esc(g.match)+'<div class="tiny muted">'+esc(g.source)+'</div>',g.hits.length?badge('前置拦截','orange')+'<div class="tiny muted mc-reason">'+esc([...new Set(g.hits.map(h=>h.rule))].join('、'))+'</div>':badge('未命中拦截','green')+(g.mode==='weak'?'<div class="tiny muted">辅助线索，需核实身份</div>':''),esc([...new Set(g.detectedMembers.map(c=>c.store))].join('、')),badge(status,['前置拦截','待审核','待执行','待重新申请'].includes(status)?'orange':status==='已合并'?'green':''),`<div class="mr-row-actions">${btn('详情',`mcOpen(${mrQuote(g.id)})`,'text')}${!['已排除'].includes(status)?btn(status==='已合并'?'合并记录':a?(a.status==='已通过'?'执行申请':'人工处理'):g.hits.length?'人工处理':'核对方案',`mcHandle(${mrQuote(g.id)})`,'text'):''}</div>`]}))+(!rows.length?empty('暂无符合条件的客户组','调整条件或重置后再试。'):'')+`<div class="pagination"><span>共 ${all.length} 组</span><div class="actions">${btn('上一页',`mcTurn(${mcPage-1})`)}<span>${mcPage} / ${pages}</span>${btn('下一页',`mcTurn(${mcPage+1})`)}</div></div>`}
function mcTurn(n){mcPage=Math.max(1,Math.min(n,Math.max(1,Math.ceil(mcRows().length/6))));render()}
function mcDrawer(){let g=state.mergeCandidates.find(x=>x.id===mrTask.id),r=mcDetailRecord(g),members=mcMembers(g),status=mgTaskFor(g)?.status||mcStatus(g),tabs=[['overview','检测概况'],['compare','档案对比'],['rules','命中规则'],['logs','处理日志']],content=mrTask.tab==='compare'?mrCompare(r,false):mrTask.tab==='rules'?mcRuleHits(g):mrTask.tab==='logs'?mgHistory(g):contentModule('客户组信息',body(mrPairCards(r)+`<div class="mr-meta">${kv({'检测编号':g.id,'处理进度':mgBadge(mgTaskFor(g)?.status||status),'检测档案数':g.detectedMembers.length+' 份','当前独立档案':members.length+' 份','匹配依据':esc(g.basis),'检测来源':g.source,'触发场景':g.trigger,'检测时间':g.time,'检测规则':esc(g.rule.name)+' V'+g.rule.version,'身份核实':g.mode==='weak'?'仅为辅助线索，需要人工核实是否同一人':'匹配身份线索后仍需核对业务数据'})}</div>`))+mcRuleHits(g)+mgHistory(g);return `<div class="merge-drawer-backdrop" onclick="if(event.target===this&&!this.dataset.closing&&!document.querySelector('#modal>[data-overlay-layer]'))mrClose()"><section id="mergeRecordPanel" class="merge-drawer" role="dialog" aria-modal="true" aria-label="合并事项详情"><header class="merge-drawer-head"><h2>合并事项详情</h2><button class="icon-btn" aria-label="关闭合并记录抽屉" onclick="mrClose()">${icon('close')}</button></header><div class="merge-drawer-body" data-drawer-scroll="merge-record"><div class="merge-rule-tabs" role="tablist" aria-label="合并详情分类">${tabs.map(([k,t],i)=>`<button class="merge-rule-tab ${mrTask.tab===k?'active':''}" role="tab" aria-selected="${mrTask.tab===k}" tabindex="${mrTask.tab===k?'0':'-1'}" onclick="mrTab('${k}')" onkeydown="mrTabKey(event,${i})">${t}</button>`).join('')}</div>${content}</div><footer class="merge-drawer-foot"><span class="mr-foot-context">${g.id} · ${g.detectedMembers.length} 份检测档案</span><div class="actions">${btn('关闭','mrClose()')}${!['已合并','已排除','已结束'].includes(status)?btn('确认不合并',`mcExcludeAsk(${mrQuote(g.id)})`):''}${status!=='已排除'?btn(status==='已合并'?'查看合并记录':status==='已结束'?'重新处理':mcActiveApplication(g)?'进入人工处理':'核对合并方案',`mcHandle(${mrQuote(g.id)})`,'primary'):''}</div></footer></section></div>`}
function mcRuleHits(g){return contentModule('前置规则检测',g.hits.length?table(['命中规则','涉及档案','判定值','处理方式'],g.hits.map(h=>[esc(h.rule),h.customerIds.map(id=>{let c=g.detectedMembers.find(c=>c.id===id);return esc(c?.name||id)+' · '+id}).join('<br>'),esc(h.value),'停止自动合并，人工核实后指定方案'])):body('<p class="small">本次检测未命中已启用的前置拦截规则。核实为同一人后可保存方案并执行合并。</p>'))}
function mcExcludeAsk(id){let g=state.mergeCandidates.find(g=>g.id===id);modal('确认整组档案不合并',`<p>将当前 ${mcMembers(g).length} 份独立档案两两加入排除名单，并关闭该检测组关联的未执行申请。</p><p class="small muted" style="margin-top:12px">仅在这些档案均为不同客户时使用；不会迁移任何数据。</p>`,btn('取消','closeModal()')+btn('确认不合并',`mcExclude(${mrQuote(id)})`,'primary'))}
function mcExclude(id){let g=state.mergeCandidates.find(g=>g.id===id);if(!g||mcMembers(g).length<2)return;let members=mcMembers(g);mrExcludeMembers(members);g.excluded=true;for(let a of state.mergeApplications.filter(a=>['待审核','已通过','执行失败'].includes(a.status)&&(a.candidateId===g.id||mrPairKey(a.pair)===mrPairKey(members)))){a.status='确认不合并';a.reviewNote='检测客户组已确认为独立客户';mrEvent(a,'整组档案确认不合并，加入排除名单')}mrEvent(g,'当前 '+members.length+' 份档案确认为独立客户，两两加入排除名单');persist();closeModal();render();toast('已确认不合并并保留处理记录')}
function mgLiveMembers(pair){let ids=pair.map(c=>{let id=c.id,seen=new Set();while(!seen.has(id)){seen.add(id);let live=state.mergeCustomers.find(x=>x.id===id);if(live?.status==='已合并-从属'&&live.mergedInto)id=live.mergedInto;else break}return id});return [...new Set(ids)].map(id=>state.mergeCustomers.find(c=>c.id===id)||pair.find(c=>c.id===id)).filter(Boolean)}
function mgApplicationRoot(a){let current=a,seen=new Set();while(current&&!seen.has(current.id)){seen.add(current.id);let previous=state.mergeApplications.find(x=>x.id===current.retryFrom||x.supersededBy===current.id);if(!previous)break;current=previous}return current||a}
function mgTasks(){
 let tasks=[],keys=new Map(),assigned=new Set();
 for(let g of state.mergeCandidates){let members=mcMembers(g),key=members.length>1?mrPairKey(members):'closed:'+g.id,t=keys.get(key);if(!t){t={key:'g:'+g.id,groups:[],apps:[],members};tasks.push(t);keys.set(key,t)}t.groups.push(g)}
 for(let a of state.mergeApplications){let t=tasks.find(t=>t.groups.some(g=>g.id===a.candidateId));if(!t&&!a.candidateId)t=tasks.find(t=>t.groups.some(g=>mrPairKey(g.detectedMembers)===mrPairKey(a.pair)||mrPairKey(t.members)===mrPairKey(a.pair)));if(t){t.apps.push(a);assigned.add(a.id)}}
 for(let a of state.mergeApplications){if(assigned.has(a.id))continue;let root=mgApplicationRoot(a),key='app:'+mrPairKey(root.pair),t=keys.get(key);if(!t){t={key:'a:'+root.id,groups:[],apps:[],members:mgLiveMembers(a.pair)};tasks.push(t);keys.set(key,t)}t.apps.push(a)}
 for(let t of tasks){
  t.apps.sort((a,b)=>b.time.localeCompare(a.time));t.g=t.groups[0];t.app=t.apps.find(a=>!a.supersededBy&&['待审核','已通过','执行失败'].includes(a.status));t.latest=t.app||t.apps[0];
  let g=t.g,a=t.latest;t.id=g?.id||a.id;t.time=g?.time||a.time;t.original=g?.detectedMembers||a.pair;
  t.reasons=[...new Set([...t.groups.flatMap(g=>g.hits.map(h=>h.reason)),...(t.app?.reasons||(!g?a?.reasons||[]:[]))])];
  t.sources=[...new Set([...t.groups.map(g=>g.hits.length?'前置拦截':'系统检测'),...t.apps.map(a=>a.source==='人工提交'||a.requestSource==='manual'||a.manualRequests?.length?'人工申请':a.source==='系统拦截'?'前置拦截':'系统检测')])];
  t.mine=t.apps.some(a=>(a.author==='张三'&&(a.source==='人工提交'||a.requestSource==='manual'))||a.manualRequests?.some(x=>x.author==='张三'));t.basis=g?.basis||a.reason;t.author=g?'系统':a.author;
  if(t.members.length<=1)t.status='已合并';else if((g&&t.groups.every(g=>g.excluded))||mrAllExcluded(t.members))t.status='已排除';else if(t.app)t.status=mgAppStatus(t.app);else if(g)t.status=t.groups.every(g=>g.closedKey===mrPairKey(t.members))?'已结束':'待核实';else t.status=mgAppStatus(a);
  t.records=state.mergeRecords.filter(r=>t.apps.some(a=>a.recordId===r.id)||t.groups.some(g=>r.candidateId===g.id||r.pair.filter(c=>g.memberIds.includes(c.id)).length>=2));
 }
 return tasks.sort((a,b)=>b.time.localeCompare(a.time));
}
function mgRows(){let f=mgApplied;return mgTasks().filter(t=>{let active=['待核实','待审核','系统执行中','待执行','执行失败'].includes(t.status),text=[t.id,t.basis,...t.groups.map(g=>g.id),...t.apps.flatMap(a=>[a.id,a.reason,a.reviewNote,...(a.manualRequests||[]).map(x=>x.reason)]),...t.original.concat(t.members).flatMap(c=>[c.id,c.name,c.phone,c.oldPhone])].join(' ').toLowerCase();return (!f.q||text.includes(uiQuery(f.q).toLowerCase()))&&(!f.store||t.original.concat(t.members).some(c=>c.store===f.store))&&(!f.status||(f.status==='pending'?active:t.status===f.status))&&(!f.source||t.sources.includes(f.source))&&(!f.mine||t.mine)&&(!f.reason||t.reasons.includes(f.reason))&&(!f.scene||t.groups.some(g=>g.trigger===f.scene)||t.apps.some(a=>a.trigger===f.scene))&&(!f.from||t.time.slice(0,10)>=f.from)&&(!f.to||t.time.slice(0,10)<=f.to)})}
function mgSearch(){if(mgFilter.from&&mgFilter.to&&mgFilter.from>mgFilter.to){toast('开始日期不能晚于结束日期');return}mgApplied=clone(mgFilter);mgPageNo=1;mgSelected.clear();render()}
function mgReset(){mgFilter={q:'',store:'',status:'pending',source:'',mine:'',reason:'',scene:'',from:'',to:''};mgSearch()}
function mgTurn(n){mgPageNo=Math.max(1,Math.min(n,Math.max(1,Math.ceil(mgRows().length/7))));render()}
function mgTabs(records){return `<div class="page-tabs" role="tablist" aria-label="客户档案合并视图">${[['merge-candidates','待合并处理'],['merge-records','合并记录']].map(([r,t],i)=>`<button id="mg-tab-${i}" class="page-tab ${(records?i===1:i===0)?'active':''}" type="button" role="tab" aria-selected="${records?i===1:i===0}" tabindex="${(records?i===1:i===0)?0:-1}" onclick="go('${r}')" onkeydown="mgTabKey(event,${i})">${t}</button>`).join('')}</div>`}
function mgTabKey(e,i){if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?1:1-i;go(n?'merge-records':'merge-candidates');setTimeout(()=>$('#mg-tab-'+n)?.focus(),32)}
function mgPage(records){
 if(records){let pool=state.mergeRecords;return mgTabs(true)+queryModule(`<div class="search">${icon('search')}<input aria-label="搜索档案合并记录" placeholder="客户姓名、手机号、档案或合并编号" value="${esc(mrFilter.q)}" oninput="mrFilter.q=this.value"></div>${select([['','全部门店'],...new Set(pool.flatMap(r=>r.pair.map(c=>c.store)))],mrFilter.store,'aria-label="合并门店" onchange="mrFilter.store=this.value"')}${select([['','全部状态'],'冷静期中','已合并','纠错中','部分已纠错','已纠错','已撤销','快照已归档'],mrFilter.status,'aria-label="合并状态" onchange="mrFilter.status=this.value"')}${select([['','全部合并方式'],'自动合并','人工合并'],mrFilter.source,'aria-label="合并方式" onchange="mrFilter.source=this.value"')}${select([['','全部触发场景'],...new Set(pool.map(r=>r.trigger))],mrFilter.scene,'aria-label="触发场景" onchange="mrFilter.scene=this.value"')}<label class="mr-date">执行日期<input type="date" aria-label="合并开始日期" value="${mrFilter.from}" onchange="mrFilter.from=this.value"><span>至</span><input type="date" aria-label="合并结束日期" value="${mrFilter.to}" onchange="mrFilter.to=this.value"></label>`,'mrSearch()','mrReset()')+contentModule('档案合并记录',`<div id="mrListRows">${mrListTable()}</div>`,'','mr-list mr-records')}
 let tasks=mgTasks(),stores=[...new Set(tasks.flatMap(t=>t.original.concat(t.members).map(c=>c.store)))],reasons=[...new Set(tasks.flatMap(t=>t.reasons))];
 return mgTabs(false)+queryModule(`<div class="search">${icon('search')}<input aria-label="搜索待合并事项" placeholder="客户姓名、手机号、档案或事项编号" value="${esc(mgFilter.q)}" oninput="mgFilter.q=this.value"></div>${select([['','全部门店'],...stores],mgFilter.store,'aria-label="处理门店" onchange="mgFilter.store=this.value"')}${select([['pending','未完成'],['','全部处理状态'],'待核实','待审核','系统执行中','待执行','执行失败','已合并','已排除','已结束'],mgFilter.status,'aria-label="处理状态" onchange="mgFilter.status=this.value"')}${select([['','全部来源'],'系统检测','前置拦截','人工申请'],mgFilter.source,'aria-label="事项来源" onchange="mgFilter.source=this.value"')}${select([['','全部事项'],['mine','我发起的']],mgFilter.mine,'aria-label="申请范围" onchange="mgFilter.mine=this.value"')}${select([['','全部触发场景'],...new Set(tasks.flatMap(t=>t.groups.concat(t.apps).map(x=>x.trigger)))],mgFilter.scene||'','aria-label="待处理触发场景" onchange="mgFilter.scene=this.value"')}${select([['','全部拦截原因'],...reasons],mgFilter.reason,'aria-label="拦截原因" onchange="mgFilter.reason=this.value"')}<label class="mr-date">创建日期<input type="date" aria-label="事项开始日期" value="${mgFilter.from}" onchange="mgFilter.from=this.value"><span>至</span><input type="date" aria-label="事项结束日期" value="${mgFilter.to}" onchange="mgFilter.to=this.value"></label>`,'mgSearch()','mgReset()')+contentModule('合并事项',`<div id="mgTaskRows">${mgList()}</div>`,btn('批量确认不合并','mgBatchAsk()')+btn('申请合并','mrNew()','primary','plus'),'mg-list');
}
function mgList(){let all=mgRows(),pages=Math.max(1,Math.ceil(all.length/7));mgPageNo=Math.max(1,Math.min(mgPageNo,pages));let rows=all.slice((mgPageNo-1)*7,mgPageNo*7);return table(['选择','事项编号 / 时间','客户档案','来源 / 发起人','核对事项','涉及门店','处理状态','操作'],rows.map(t=>{let selectable=['待核实','执行失败'].includes(t.status),display=['已合并','已排除','已结束'].includes(t.status)?t.original:t.members,action=t.app?.review?'查看审核':t.status==='执行失败'?'重新核对':'核对合并方案';return [selectable?`<input type="checkbox" aria-label="选择合并事项 ${t.id}" ${mgSelected.has(t.key)?'checked':''} onchange="mgToggle(${esc(mrQuote(t.key))},this.checked)">`:'—',`<button class="inline-link mono" onclick="mgOpen(${esc(mrQuote(t.key))})">${esc(t.id)}</button><div class="tiny muted">${esc(t.time.slice(0,16))}</div>`,`<strong>${display.length} 份档案</strong><div class="tiny">${display.map(c=>esc(c.name)).join('、')}</div>${t.members.length<t.original.length&&t.members.length>1?`<div class="mg-task-meta">原检测 ${t.original.length} 份，剩余 ${t.members.length} 份待处理</div>`:''}`,`<div class="mg-source">${t.sources.map(s=>badge(s,s==='前置拦截'?'orange':'')).join('')}</div><div class="tiny muted">${esc(t.g?.source||t.author)}</div>${t.mine?'<div class="tiny muted">包含我发起的申请</div>':''}`,t.status==='执行失败'?`<div class="mr-clamp">${esc(t.app?.logs.find(l=>l.content.includes('执行失败'))?.content||'执行未完成，请重新核对档案状态')}</div>`:t.reasons.length?`<div class="mr-clamp">${esc(t.reasons.join('；'))}</div>`:`<div class="mr-clamp">${esc(t.basis)}</div>`,esc([...new Set(t.original.map(c=>c.store))].join('、')),mgBadge(t.status),`<div class="mr-row-actions">${btn('详情',`mgOpen(${mrQuote(t.key)})`,'text')}${['待核实','待审核','系统执行中','待执行','执行失败'].includes(t.status)?btn(action,`mgOpen(${mrQuote(t.key)},true)`,'text'):t.records.length?btn('合并记录',`mgShowRecord(${mrQuote(t.key)})`,'text'):''}</div>`]}))+(!rows.length?empty('暂无符合条件的合并事项','调整条件或重置后再试。'):'')+`<div class="pagination"><span>共 ${all.length} 项<span id="mgSelectedSummary">${mgSelected.size?' · 已选 '+mgSelected.size+' 项':''}</span></span><div class="actions">${btn('上一页',`mgTurn(${mgPageNo-1})`)}<span>${mgPageNo} / ${pages}</span>${btn('下一页',`mgTurn(${mgPageNo+1})`)}</div></div>`}
function mgOpenLoaded(key,handle=false){let t=mgTasks().find(t=>t.key===key);if(!t)return;if(t.app?.review){apOpen('merge',t.app.id);return}if(t.app){mrOpen('application',t.app.id);if(handle){mrTask.tab=t.app.status==='已通过'?'confirm':t.app.status==='执行失败'?'overview':'compare';render()}return}if(t.g){if(handle&&!['已排除','已结束','已合并'].includes(t.status)){mrNew(undefined,t.g.id);mrTask.tab='compare';render()}else mcOpen(t.g.id);return}mrOpen('application',t.latest.id)}
function mgShowRecord(key){let t=mgTasks().find(t=>t.key===key),r=t?.records[0];if(r)mrOpen('record',r.id)}
function mgTaskFor(r){return mgTasks().find(t=>t.groups.some(g=>g.id===r.id||g.id===r.candidateId)||t.apps.some(a=>a.id===r.id))}
function mgDetection(r){let g=state.mergeCandidates.find(g=>g.id===r.candidateId);if(!g)return contentModule('检测依据',body('<p class="small muted">本次由人工选择档案并发起申请。</p>'));return contentModule('系统检测依据',body(kv({'检测编号':g.id,'检测来源':g.source,'检测时间':g.time,'触发场景':g.trigger,'匹配依据':esc(g.basis),'原检测档案':g.detectedMembers.length+' 份','当前独立档案':mcMembers(g).length+' 份','检测规则':esc(g.rule.name)+' V'+g.rule.version})))+mcRuleHits(g)}
function mgLinkedResults(r){let t=mgTaskFor(r);if(!t?.records.length)return '';return contentModule('关联的合并记录',table(['合并编号','执行时间','参与档案','当前状态','操作'],t.records.map(x=>[x.id,x.time,x.pair.length+' 份',mrBadge(mrStatus(x)),btn('查看记录',`mrOpen('record',${mrQuote(x.id)})`,'text')])))}
function mgHistory(r){let t=mgTaskFor(r);if(!t)return mrLogs(r);let seen=new Set(),logs=t.groups.concat(t.apps).flatMap(x=>x.logs||[]).filter(l=>{let key=[l.at,l.by,l.content].join('|');if(seen.has(key))return false;seen.add(key);return true}).sort((a,b)=>b.at.localeCompare(a.at));return (t.apps.length?contentModule('申请与方案记录',table(['申请编号','来源 / 申请人','处理状态','提交时间','操作'],t.apps.map(a=>[a.id,esc(a.source)+' / '+esc(a.author),mgBadge(mgAppStatus(a)),a.time,btn(a.id===r.id?'当前申请':'查看',a.id===r.id?"mrTab('overview')":`mrOpen('application',${mrQuote(a.id)})`,'text')]))):'')+mrLogs({logs})+mgLinkedResults(r)}
function mgSaveDetectedPlan(){mrSubmit()}
function mgEditPlan(){let a=mrCurrent();if(!a||a.status!=='已通过')return;let draft=state.mergeReviewDrafts?.[a.id];mrTask.plan=clone(draft?.plan||a.plan);mrTask.applicationEdit=clone(draft?.form||{reason:a.reason||'',reasonType:a.reasonType||'同一客户重复建档',evidence:a.evidence||[]});mrTask.inspectCustomerId=draft?.inspectCustomerId||a.plan.mainId;mrTask.editingPlan=true;if(mrTask.plan.mainChosen===undefined)mrTask.plan.mainChosen=a.pair.some(c=>c.id===mrTask.plan.mainId);maPrepare(a);mrTask.tab=draft?.tab&&MA_STEPS.some(x=>x[0]===draft.tab)?draft.tab:'confirm';mrTask.dirty=false;render()}
function mgToggle(key,on){on?mgSelected.add(key):mgSelected.delete(key);let el=$('#mgSelectedSummary');if(el)el.textContent=mgSelected.size?' · 已选 '+mgSelected.size+' 项':''}
function mgBatchAsk(){let tasks=mgTasks().filter(t=>mgSelected.has(t.key)&&['待核实','执行失败'].includes(t.status));if(!tasks.length){toast('请先选择需要确认不合并的事项');return}modal('批量确认不合并',`<p>将选中的 ${tasks.length} 项事项内，各组当前档案分别两两加入排除名单，不迁移任何数据。</p><p class="mg-batch-summary">仅在每组内所有档案均属于不同客户时使用；若部分档案属于同一人，请先逐项处理。</p>`+table(['事项编号','档案','数量'],tasks.map(t=>[t.id,t.members.map(c=>esc(c.name)).join('、'),t.members.length+' 份'])),btn('取消','closeModal()')+btn('确认不合并','mgBatchCommit()','primary'),true)}
function mgBatchCommit(){let tasks=mgTasks().filter(t=>mgSelected.has(t.key)&&['待核实','执行失败'].includes(t.status));for(let t of tasks){mrExcludeMembers(t.members);for(let g of t.groups){g.excluded=true;mrEvent(g,'批量确认为独立客户，各档案两两加入排除名单')}for(let a of t.apps.filter(a=>['待审核','已通过','执行失败'].includes(a.status))){a.status='确认不合并';a.reviewNote='批量核实为独立客户';mrEvent(a,'批量确认不合并，未迁移数据')}}mgSelected.clear();persist();closeModal();render();toast(tasks.length+' 项事项已确认不合并')}
function mgFinishAsk(){let a=mrCurrent();if(!a||a.status!=='待审核')return;modal('结束本次处理','<p>结束当前事项，保留申请、核对资料和处理日志，不迁移档案数据，也不加入“不合并”排除名单。</p>'+field('处理说明（选填）','<textarea id="mgFinishNote" aria-label="结束处理说明" placeholder="例如：申请重复、暂不处理"></textarea>'),btn('继续处理','closeModal()')+btn('结束处理','mgFinishCommit()','primary'))}
function mgFinishCommit(){let a=mrCurrent();if(!a||a.status!=='待审核')return;a.status='已撤回';a.reviewNote=$('#mgFinishNote')?.value.trim()||'结束本次处理';a.reviewedAt=now();let g=state.mergeCandidates.find(g=>g.id===a.candidateId);if(g&&mrPairKey(mcMembers(g))===mrPairKey(a.pair))g.closedKey=mrPairKey(mcMembers(g));mrEvent(a,'结束处理：'+a.reviewNote+'；未迁移数据，未加入排除名单');mrTask.dirty=false;persist();closeModal();render();toast('处理已结束，记录已保留')}
function mgAttachRequest(a){if(mrTask.candidateId)return;a.manualRequests||=[];let reason=mrTask.reason.trim()||'未填写核实说明',evidence=clone(mrTask.evidence),proposal={pair:clone(mrTask.pair),plan:clone(mrTask.plan),reasonType:mrTask.reasonType};if(!a.manualRequests.some(x=>x.author==='张三'&&x.reason===reason&&JSON.stringify(x.evidence)===JSON.stringify(evidence)&&JSON.stringify(x.proposal)===JSON.stringify(proposal))){a.manualRequests.push({author:'张三',time:now(),reason,evidence,proposal});for(let f of evidence)if(!a.evidence.includes(f))a.evidence.push(f);mrEvent(a,'收到张三补充的合并申请与拟定方案：'+reason+'；沿用现有事项，不覆盖已保存的处理方案')}}
function mgRequestNotes(r){if(!r.manualRequests?.length)return '';return contentModule('补充的人工申请',table(['发起人','提交时间','申请说明','材料','操作'],r.manualRequests.map((x,i)=>[esc(x.author),x.time,esc(x.reason),x.evidence.map(esc).join('、')||'无',x.proposal?btn('查看申请方案',`maRequestPreview(${i})`,'text'):'—'])))}
function maRequestPreview(index){let r=maRecord(),request=r.manualRequests?.[index],proposal=request?.proposal;if(!proposal)return;let p=mrImpact(proposal.pair,proposal.plan);modal('补充申请的拟定方案',body(kv({'申请人':esc(request.author),'申请说明':esc(request.reason),'参与档案':proposal.pair.map(c=>esc(c.name)).join(' + '),'主档案':esc(p.main.name)+' · '+uiId(p.main.id),'合并后姓名':esc(p.after.name),'主手机号':esc(p.after.phone),'保留手机号':p.after.phones.map(esc).join('、'),'UnionID':p.after.unionIds.map(esc).join('、'),'企微ID':p.after.externalIds.map(esc).join('、')}))+table(['订单','来源档案','拟定处理','依据'],p.all.map(o=>[uiId(o.id),esc(proposal.pair.find(c=>c.id===o.origin)?.name||''),p.returned.some(x=>x.id===o.id)?'合并流退':'保留',esc(proposal.plan.orderReasons?.[o.id]||'—')])),btn('返回申请记录','maViewHistory()')+(r.status==='待审核'?btn('带入核对草稿',`maUseRequest(${index})`,'primary'):''),true)}
function maUseRequest(index){let r=maRecord(),request=r.manualRequests?.[index];if(r.status!=='待审核'||!request?.proposal)return;mrTask.plan=clone(request.proposal.plan);mrTask.applicationEdit={reason:request.reason,reasonType:request.proposal.reasonType||'同一客户重复建档',evidence:clone(request.evidence)};maPrepare(r);maMarkDirty();mrTask.tab='confirm';closeModal();render();toast('已带入核对草稿，保存后才更新正式方案')}
function pcViewRecordLoaded(id,tab='overview'){let r=state.mergeRecords.find(r=>r.id===id);if(!r)return;let key=MH_TABS.some(x=>x[0]===tab)?tab:'overview',previous=pcRecordModalState;pcRecordModalState={id,tab:key,snapshotId:previous?.id===id?previous.snapshotId:''};modal('合并记录',`<div class="mh-shell">${mhTabs(r,key,true)}<div class="mh-nested-content mh-view"><div id="mh-nested-content" role="tabpanel" aria-labelledby="mh-nested-${key}">${mhContent(r,key,true)}</div></div></div>`,(pcModalCustomer?btn('返回客户档案','pcCustomerModal()'):'')+btn('关闭','closeModal()'),true)}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&window.PCUI?.isPopupOpen())return;if(!mrTask||cxWorkbenchId||cxApplicationOpen||mergeEditor)return;let nested=document.querySelector('#modal>[data-overlay-layer]:not(.is-closing) [role=dialog]'),top=nested||document.querySelector('[data-overlay-layer="merge-record"]:not(.is-closing) [role=dialog]');if(!top)return;if(e.key==='Escape'){e.preventDefault();nested?closeModal():mrClose();return}if(e.key==='Tab'){let items=[...top.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled&&x.getClientRects().length),a=items[0],b=items.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus()}}});
window.PCModules["customer-merge"]=PCModules['customer-engine'].page({"merge-candidates":mergeCandidatesPage,"merge-records":mergeRecordsPage},{pcViewRecord:pcViewRecordLoaded,mrOpen:mrOpenLoaded,mrNew:mrNewLoaded,mcOpen:mcOpenLoaded,mgOpen:mgOpenLoaded});
